{
    "description": "Creates a new generic.InjectModule definition in the given or default project.",
    "required": ["name"],
    "title": "Angular Module Options Schema",
    "type": "object",
    "properties": {
        "commonModule": {
            "default": true,
            "description": "When true, the new module imports \"CommonModule\".",
            "type": "boolean"
        },
        "flat": {
            "default": false,
            "description": "When true, creates the new files at the top level of the current project root.",
            "type": "boolean"
        },
        "lintFix": {
            "default": false,
            "description": "When true, applies lint fixes after generating the module.",
            "type": "boolean",
            "x-user-analytics": 15
        },
        "module": {
            "alias": "m",
            "description": "The declaring module.",
            "type": "string"
        },
        "name": {
            "$default": {
                "$source": "argv",
                "index": 0
            },
            "description": "The name of the module.",
            "type": "string",
            "x-prompt": "What name would you like to use for the module?"
        },
        "path": {
            "description": "The path at which to create the module, relative to the workspace root.",
            "format": "path",
            "type": "string",
            "visible": false
        },
        "project": {
            "$default": {
                "$source": "projectName"
            },
            "description": "The name of the project.",
            "type": "string"
        },
        "route": {
            "description": "The route path for a lazy-loaded module. When supplied, creates a component in the new module, and adds the route to that component in the `Routes` array declared in the module provided in the `--module` option.",
            "type": "string"
        },
        "routing": {
            "default": false,
            "description": "When true, creates a routing module.",
            "type": "boolean",
            "x-user-analytics": 17
        },
        "routingScope": {
            "default": "Child",
            "description": "The scope for the new routing module.",
            "enum": [
                "Child",
                "Root"
            ],
            "type": "string"
        }
    }
}

